"""Named Actor contracts; imported only after the native Actor build is ready."""

import unreal
import toolset_registry

from .results import CubelessPythonOperationResult, reflected_result
from . import actor_transform_schema as _actor_transform_schema
from cubeless_mcp_ue58.operations import actor


@unreal.uclass()
class CubelessActorTools(unreal.ToolsetDefinition):
    """Cubeless loaded Actor inspection and single saved /Game persistent-level editing; no streaming/WP/external actors for mutations, no automatic compile/save. The existing six-input transform adapter limits its JSON carriers to 512 UTF-16 units and component magnitudes to 1e12; the separate original four-input nullable-array parser remains Native-owned."""

    @toolset_registry.tool_call
    @staticmethod
    def get_actors_in_level(expected_level_path: str | None = None) -> CubelessPythonOperationResult:
        """List up to 10000 loaded editor-world actors with object names and transforms. Includes loaded sublevels; not unloaded World Partition cells.

        Args:
            expected_level_path: Optional exact persistent-level package path, such as /Game/Maps/MyMap; mismatch fails.
        """
        return reflected_result(actor.get_actors_in_level(expected_level_path))

    @toolset_registry.tool_call
    @staticmethod
    def find_actors_by_name(pattern: str, expected_level_path: str | None = None) -> CubelessPythonOperationResult:
        """Find loaded actors by case-insensitive substring of UObject name, not display label. Empty pattern lists all; bounded at 10000 actors.

        Args:
            pattern: Object-name substring, at most 4096 UTF-16 units; empty string matches every loaded actor.
            expected_level_path: Optional exact persistent-level package path; mismatch fails.
        """
        return reflected_result(actor.find_actors_by_name(pattern, expected_level_path))

    @toolset_registry.tool_call
    @staticmethod
    def get_actor_properties(name: str, expected_level_path: str | None = None) -> CubelessPythonOperationResult:
        """Read exact object-name actor identity and legacy name/class/location/rotation/scale fields; this is not arbitrary reflected property enumeration. This same before-read carries basic identity for the bounded Actor Blueprint instance mutation route; read success alone does not grant mutation admission or source-preservation proof.

        Args:
            name: Exact case-sensitive UObject actor name, not display label; duplicate names across loaded levels fail as ambiguous.
            expected_level_path: Optional exact persistent-level package path; mismatch fails.
        """
        return reflected_result(actor.get_actor_properties(name, expected_level_path))

    @toolset_registry.tool_call
    @staticmethod
    def spawn_actor(name: str, type: str, location_json: str = "[0,0,0]", rotation_json: str = "[0,0,0]", scale_json: str = "[1,1,1]", expected_level_path: str | None = None, operation_id: str | None = None) -> CubelessPythonOperationResult:
        """Spawn one supported native actor with an exact object name and verify its transform. Saved /Game persistent level only; World Partition/external actors excluded.

        Args:
            name: Exact new UObject actor name, not display label, at most 1023 UTF-16 units. Existing object-name collisions fail.
            type: StaticMeshActor, PointLight, SpotLight, DirectionalLight or CameraActor; spelling is case-insensitive.
            location_json: JSON string encoding three finite world XYZ numbers; component magnitude at most 1e12, text at most 512 UTF-16 units; default [0,0,0].
            rotation_json: JSON string encoding finite Pitch/Yaw/Roll degrees, magnitude at most 1e12 and text at most 512 UTF-16 units; default [0,0,0].
            scale_json: JSON string encoding finite XYZ scale, magnitude at most 1e12 and text at most 512 UTF-16 units; default [1,1,1]. Extends the legacy public wrapper's native scale support.
            expected_level_path: Optional exact saved persistent-level package path. Omission still pins the inspected level before dispatch.
            operation_id: Unique durable request ID; omitted/null generates an ID returned in the result. Identical completed requests replay evidence without mutation.
        """
        return reflected_result(actor.spawn_actor(name, type, location_json, rotation_json, scale_json, expected_level_path, operation_id))

    @toolset_registry.tool_call
    @staticmethod
    def create_actor(name: str, type: str, location_json: str = "[0,0,0]", rotation_json: str = "[0,0,0]", scale_json: str = "[1,1,1]", expected_level_path: str | None = None, operation_id: str | None = None) -> CubelessPythonOperationResult:
        """Preserve the legacy internal create_actor alias using the same spawn core. Alias has its own journal identity; no automatic compile/save or rollback.

        Args:
            name: Exact new UObject actor name, not display label; collisions fail.
            type: StaticMeshActor, PointLight, SpotLight, DirectionalLight or CameraActor; case-insensitive.
            location_json: JSON string with finite world XYZ; magnitudes at most 1e12, text at most 512 UTF-16 units; default [0,0,0].
            rotation_json: JSON string with finite Pitch/Yaw/Roll degrees; magnitudes at most 1e12, text at most 512 UTF-16 units; default [0,0,0].
            scale_json: JSON string with finite XYZ scale; magnitudes at most 1e12, text at most 512 UTF-16 units; default [1,1,1].
            expected_level_path: Optional exact saved /Game persistent-level package path. World Partition and external actors are unsupported.
            operation_id: Unique durable ID; omitted/null generates one. Reusing a spawn_actor ID here is an operation conflict.
        """
        return reflected_result(actor.create_actor(name, type, location_json, rotation_json, scale_json, expected_level_path, operation_id))

    @toolset_registry.tool_call
    @staticmethod
    def spawn_blueprint_actor(blueprint_name: str, actor_name: str, location_json: str = "[0,0,0]", rotation_json: str = "[0,0,0]", scale_json: str = "[1,1,1]", expected_level_path: str | None = None, operation_id: str | None = None) -> CubelessPythonOperationResult:
        """Spawn a compiled, clean, saved /Game Actor Blueprint with an exact UObject name. No explicit compile/save; asset loading can trigger PostLoad work. Construction scripts execute; arbitrary side effects and rollback are not guaranteed. Saved dependency inspection is bounded at 256 packages. Native parents are limited to Engine/CoreUObject; dependencies use /Game, /Engine and the audited Engine/CoreUObject/PhysicsCore/MeshDescription/StaticMeshDescription/NavigationSystem modules.

        Args:
            blueprint_name: Exact /Game Blueprint asset package/object path, or simple name under /Game/Blueprints. Generated-class paths and editor-only/tool dependencies are rejected.
            actor_name: Exact new UObject actor name, not display label; case-insensitive collisions fail before spawn.
            location_json: JSON string with finite XYZ world location; magnitudes at most 1e12, text at most 512 UTF-16 units.
            rotation_json: JSON string with finite Pitch/Yaw/Roll degrees; same bounds.
            scale_json: JSON string with finite XYZ scale; default [1,1,1], same bounds.
            expected_level_path: Optional exact saved /Game persistent-level package path; omission pins inspected level. One non-WP level without external actors only.
            operation_id: Unique durable request ID; omitted/null generates one. No automatic retry of an uncertain mutation.
        """
        return reflected_result(actor.spawn_blueprint_actor(blueprint_name, actor_name, location_json, rotation_json, scale_json, expected_level_path, operation_id))

    @toolset_registry.tool_call
    @staticmethod
    def delete_actor(name: str, expected_level_path: str | None = None, operation_id: str | None = None) -> CubelessPythonOperationResult:
        """Delete an exact-name actor and independently verify absence. Existing unattached instances of the five native spawn classes or exact native TargetPoint remain admitted in one saved /Game non-WP persistent level. A separate finite route deletes an exact native TargetPoint leaf attached to an exact SceneComponent root of an exact native TargetPoint parent in the same supported level. The parent is itself unattached and has this target as its sole attached Actor; the target has no attached child Actors and no Actor Owner. Both roots require no socket and all absolute flags false, and parent-before/target-before world scales must be positive uniform with each axis at most 1e12. These are finite adapter conditions rather than general Engine deletion limits. The native parent/root and captured nonselected state remain protected while the selected target retires and its parent attachment membership is removed. Engine-owned detach and normal parent Modify bookkeeping are distinguished from authored transform or other membership changes. Captured actual destroy acceptance, retirement, parent/attachment and failure/unknown observations remain authoritative; a returned bool alone is not preservation proof. An accepted deletion permits only removal of the selected attachment membership while retaining the ordered remaining list and parent world/relative transform. Retired target fields are not reread. A false DestroyActor return may remain unknown because Editor selection/layer/delegate work could already have occurred; it is not promoted to a known no-op. Existing before-read, effective-level guard, durable pre-mutation checkpoint and complete returned Native data/failure handling remain unchanged. No Python detach, second delete, compile, map save, rollback or automatic retry is added. The original required name-only public input differs from the current name/expected_level_path/operation_id three-input surface; no schema identity is claimed. The original Actor::Destroy handler and the current public EditorActorSubsystem delete path have different Editor selection/layer/delegate work. A separate native parent-delete route admits one unattached exact TargetPoint, StaticMeshActor, PointLight, SpotLight, DirectionalLight or CameraActor parent with 1..8 direct exact StaticMeshActor children in the same saved supported level. The parent and children are unowned, use native Engine components, and have positive uniform bounded world scale; children are unselected leaves. Root socket and absolute flags must be absent, with no simulated or welded primitive components. Native retains each surviving child component actual nullable World role, identity and internal attachment roles, plans root detachment with KeepWorldTransform, and checks child world/relative transforms within 0.01 after the existing EditorActorSubsystem destroy call. No Python detach is synthesized. Only the selected parent retires; returned false or failed postconditions preserve the actual attempted/returned prefix and unknown state without further delete or retry. Global selection/layer/navigation/delegate effects and arbitrary private/component/cache state are not completely observed. Broader valid original parent/child types, deeper subtrees, selected children, sockets, scale/absolute variants and arbitrary callbacks remain incomplete; this authors Editor deletion, without runtime or whole original parity proof. A separate bounded route admits a loaded instance of a saved-clean normal Blueprint directly derived from AActor, with no own variables or interfaces, one authored exact native Scene SCS root role, no Actor attachment/Owner/children, and no dynamic delegate bindings, AddComponent templates or timelines. The instance may also own one bounded exact native UBillboardComponent editor visualization as a direct root child, for 1..2 Actor components and 0..1 root children. This requires root bVisualizeComponent, visualization/editor-only state, RF_Transient|RF_TextExportTransient, the same Actor owner/outer/world and root CreationMethod, Movable, no sprite child/socket, absolute location/rotation false and stock Billboard absolute scale true. Captured sprite relative transform and tags remain protected across reconstruction; sprite name/address and Actor component order may change. This finite observed role is not proof of the private SpriteComponent slot. Native observes actual UserConstructionScript, ReceiveDestroyed and ReceiveEndPlay functions and requires each to be absent or have empty Script; this is not arbitrary callback support. Captured source/class/CDO/graph/pin/dependency and nonselected state remain Native-owned. Accepted deletion retires the selected instance without reading its fields again; source/current and actual retirement receipts are separate from destroy acceptance. Broader Blueprint parents/components/variables/nonempty lifecycle scripts and arbitrary callbacks remain incomplete. A delete-only expansion admits a bounded closed tree of 1..64 own native Engine Scene-derived SCS components on the same saved-clean direct Actor Blueprint profile. Native retains ordered source nodes, GUIDs, compiled member bindings and directly reflected editable template/instance values through typed descriptor checks; unsupported authored values remain valid incomplete scope. No component class-name sample exception is used. The selected actor and all captured instance components retire together immediately after the existing destroy return; source Blueprint and surviving actors remain checked. This does not expand transform, attachment, lifecycle-script, unreflected native state or global callback support. Batch has no delete_actor allowlist entry.

        Args:
            name: Exact case-sensitive UObject actor name; missing/ambiguous actors fail. Existing unattached native scopes, the finite attached leaf TargetPoint profile, the bounded native parent-delete profile and the direct Actor Blueprint instance profile above are admitted. Blueprint templates, ChildActor and broader Blueprint/attachment scopes remain incomplete.
            expected_level_path: Optional exact persistent-level package path; omission pins the inspected level. No map save occurs.
            operation_id: Unique durable request ID; omitted/null generates one. No automatic retry or atomic rollback.
        """
        return reflected_result(actor.delete_actor(name, expected_level_path, operation_id))

    @toolset_registry.tool_call
    @staticmethod
    def set_actor_transform(name: str, location_json: str = "null", rotation_json: str = "null", scale_json: str = "null", expected_level_path: str | None = None, operation_id: str | None = None) -> CubelessPythonOperationResult:
        "Patch a supported actor's world transform and read it back. Each JSON null preserves that component; all null is an inspected no-op. Existing unattached mutation scopes remain unchanged. A separate bounded parent-move profile admits an exact native StaticMeshActor parent with a closed acyclic native StaticMeshActor descendant tree in the same saved persistent level, up to 32 Actors/depth8 and one own registered native StaticMeshComponent root each. Owner, socket, absolute transform, simulation, welding and deferred-movement modes remain excluded in this finite profile. Positive uniform captured/requested scales are bounded by 1e12. One Engine transform writer moves the parent; captured relative chains determine planned descendant world transforms. Native verifies actual world propagation while preserving descendant relative transforms, ordered attachment, held identities and captured source/authored fields. Returned typed-element acceptance alone does not prove the underlying transform or child propagation. Other valid classes/components/physics/scales/deeper conditions remain incomplete; no new deletion, reparent, save or runtime operation is added. A separate transform-only route admits an exact native TargetPoint target attached to the exact SceneComponent root of one exact native TargetPoint parent in the same saved supported persistent level. The parent is itself unattached and has only this attached Actor; the target has no attached child Actors. Both roots require no socket and all absolute location/rotation/scale flags false, and this attached route requires positive uniform world scales, each axis at most 1e12, for the parent before, target before and desired target transform. These are finite attached-profile conditions, not a reclassification of all nonuniform transforms as invalid. Native retains parent/root/component identity and attachment membership/order, permits the planned target world/relative change and uses the Engine world-to-relative calculation. Actual parent/target world/relative and partial/current observations stay separate; returned acceptance alone is not preservation proof. Broader parents/types/scales/sockets/absolute modes/custom callbacks remain incomplete, and Delete, attach or reparent admission is not expanded. Original public name/location/rotation/scale four-input nullable-array surface differs from this current six-input JSON-string adapter plus expected_level_path/operation_id; no schema identity is claimed. The existing before-read, durable checkpoint and transform order is preserved. This authors Editor state without simulation/runtime proof, explicit compile or map save. Batch has no ActorTransform allowlist entry; the separate ActorPropertyFocus tools are not equivalent. The existing single-root Blueprint route admits a loaded instance of a saved-clean normal Blueprint directly derived from AActor, with no own variables or interfaces, one authored exact native Scene SCS root role, no Actor attachment/Owner/children, and no dynamic delegate bindings, AddComponent templates or timelines. The instance may also own one bounded exact native UBillboardComponent editor visualization as a direct root child, for 1..2 Actor components and 0..1 root children. This requires root bVisualizeComponent, visualization/editor-only state, RF_Transient|RF_TextExportTransient, the same Actor owner/outer/world and root CreationMethod, Movable, no sprite child/socket, absolute location/rotation false and stock Billboard absolute scale true. Captured sprite relative transform and tags remain protected across reconstruction; sprite name/address and Actor component order may change. This finite observed role is not proof of the private SpriteComponent slot. Native observes actual UserConstructionScript, ReceiveDestroyed and ReceiveEndPlay functions and requires each to be absent or have empty Script; this is not arbitrary callback support. Source class/CDO/graphs/pins/dependency audit and instance current state are protected within their captured scope. PostEditMove can rerun construction and replace the physical root. Native reacquires only the exact native Scene logical root through resolved Actor RootComponent and own SCS property slots, then verifies actual final transform/current state. Physical address change alone proves neither success nor failure. EditorElementSubsystem acceptance is separate from the underlying transform result and final postconditions. Broader Blueprint parents/components/variables/lifecycle scripts, attachments and arbitrary callbacks remain incomplete; no runtime behavior is verified. An additional own-SCS Blueprint transform profile retains the existing source/lifecycle admission and admits an own closed tree of 1..64 Native-admitted Engine Scene-derived SCS components on a direct Actor Blueprint. The instance is unattached, without sockets, absolute location/rotation, simulation or welding; nonvisual components also require absolute scale false. Root and local scales must be positive finite uniform values within Native bounds. Captured stock editor Billboard absolute-scale behavior is modeled separately. Native protects source templates, GUID/member bindings, graph/CDO/file roles and child authored relative transforms, instance tags and other admitted editable values, while planning descendant world transforms from the requested parent world transform. The six-input editor path can rerun construction: old component addresses are not a preservation requirement, and fresh component roles are reacquired through source member/GUID and logical parent bindings before readback. The separate original four-input path retains one direct setter and physical-component preservation, without adding editor movement callbacks. For reconstructed FText values, only native empty or identified Base histories with captured source, namespace, key and flags are admitted; StringTable, dynamic or unidentified histories remain original-valid prewriter pending. Source and same-physical TextData identity remain strict. This is finite source/instance observation, not complete construction, renderer, physics-cache or global-effect proof. Inherited/custom/opaque components, nonuniform scales, sockets, physics and other original-valid variants remain incomplete.\n\n        Args:\n            name: Exact case-sensitive UObject actor name; ambiguity fails. Existing unattached five native spawn classes or exact native TargetPoint remain supported, plus the separate bounded attached TargetPoint transform profile and Native-admitted direct Actor Blueprint instance profiles described above. Blueprint templates, ChildActor and broader Blueprint/attachment scopes remain incomplete.\n            location_json: JSON string with three finite XYZ values, or the string null to preserve location. Magnitudes at most 1e12, text at most 512 UTF-16 units.\n            rotation_json: JSON string with finite Pitch/Yaw/Roll degrees, or the string null to preserve rotation. Magnitudes at most 1e12, text at most 512 UTF-16 units.\n            scale_json: JSON string with three finite XYZ values, or the string null to preserve scale. Magnitudes at most 1e12, text at most 512 UTF-16 units.\n            expected_level_path: Optional exact saved /Game non-WP persistent-level package path; omission pins the inspected level. No map save occurs.\n            operation_id: Unique durable ID; omitted/null generates one. Inspect partial/uncertain changes before a new request.\n        "
        return reflected_result(actor.set_actor_transform(name, location_json, rotation_json, scale_json, expected_level_path, operation_id))


    @toolset_registry.tool_call
    @staticmethod
    def set_actor_transform_original(name: str, location_json: str = "null", rotation_json: str = "null", scale_json: str = "null") -> str:
        'Set actor transform through the original four-input nullable-array contract. The registered raw adapter exposes location, rotation and scale as arrays or null; these FString names are physical carriers only. Null preserves a transform, short arrays become zero and longer arrays use the first three float32 values. The shared Native scope/current and partial/unknown receipt remain authoritative. No compile, save, rollback or automatic replay is added; this is separate from the unchanged six-input set_actor_transform adapter. An actual original actor mutation result is returned when available, otherwise the real failure or unknown receipt is retained. The additional own-SCS Blueprint profile shares Native source/current admission with the six-input tool, but uses the original direct setter once, including name-only/no-op requests; it preserves captured physical component roles and child authored relative state while checking planned root and child world propagation. It does not add PostEditMove, construction rerun, transaction, explicit compile or save. Wider original-valid scopes remain incomplete.'
        return _actor_transform_schema.invoke_carriers(CubelessActorTools, actor.set_actor_transform_original,
            name, location_json, rotation_json, scale_json)
